import React, { useState, useEffect, useContext } from 'react';
import { Link } from 'react-router-dom';
import Icon from 'components/AppIcon';
import api from '../../lib/api';
import { ProgressContext } from '../../contexts/ProgressContext';
import LoadingState from '../../components/ui/LoadingState';
import WeeklyCalendar from './components/WeeklyCalendar';

const SUBJECTS = ['all', 'mathematics', 'programming', 'science', 'history', 'geography', 'literature'];

const StudyPlannerPage = () => {
  const { learningNodes = [] } = useContext(ProgressContext) || {};
  const [planData, setPlanData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);

  // Builder state
  const [showBuilder, setShowBuilder] = useState(false);
  const [catalog, setCatalog] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [subjectFilter, setSubjectFilter] = useState('all');
  const [selectedIds, setSelectedIds] = useState([]);
  const [customTopics, setCustomTopics] = useState('');
  const [weeklyHours, setWeeklyHours] = useState(5);
  const [planTitle, setPlanTitle] = useState('My Study Plan');

  const loadPlan = () => {
    setLoading(true);
    api.getActiveStudyPlan()
      .then(setPlanData)
      .catch(() => setPlanData(null))
      .finally(() => setLoading(false));
  };

  useEffect(() => { loadPlan(); }, []);

  const openBuilder = async () => {
    setShowBuilder(true);
    try {
      const data = await api.getCatalog();
      setCatalog(Array.isArray(data) ? data : []);
    } catch {
      setCatalog([]);
    }
  };

  const filteredCatalog = catalog.filter((item) => {
    const q = searchQuery.toLowerCase();
    const matchesSearch = !q
      || (item.title || '').toLowerCase().includes(q)
      || (item.description || '').toLowerCase().includes(q)
      || (item.concepts || []).some((c) => c.toLowerCase().includes(q));
    const matchesSubject = subjectFilter === 'all' || item.subject === subjectFilter;
    return matchesSearch && matchesSubject;
  });

  const toggleSelect = (id) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]
    );
  };

  const createPlan = async () => {
    if (selectedIds.length === 0 && !customTopics.trim()) return;
    setCreating(true);
    try {
      await api.createStudyPlan({
        title: planTitle || 'My Study Plan',
        weeklyMinutes: Math.round(weeklyHours * 60),
        nodeIds: selectedIds,
        customTopics: customTopics.trim() || undefined,
      });
      setShowBuilder(false);
      setSelectedIds([]);
      setCustomTopics('');
      loadPlan();
    } finally {
      setCreating(false);
    }
  };

  const toggleDay = async (day) => {
    if (!planData?.plan) return;
    const entry = planData.calendar.find((e) => e.day === day);
    await api.updateStudyPlanDay(planData.plan.id, day, { completed: !entry?.completed });
    loadPlan();
  };

  if (loading) return <LoadingState message="Loading study plan..." />;

  const selectedItems = catalog.filter((c) => selectedIds.includes(c.id));

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-8 max-w-4xl">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-8">
          <div>
            <h1 className="text-2xl lg:text-3xl font-heading font-bold text-text-primary">Study Planner</h1>
            <p className="text-text-secondary mt-1">Pick topics, set your hours, build your week</p>
          </div>
          <div className="flex gap-2">
            {planData?.plan && (
              <button onClick={openBuilder} className="btn btn-outline px-4 py-2 text-sm">
                New Plan
              </button>
            )}
            {!planData?.plan && !showBuilder && (
              <button onClick={openBuilder} className="btn btn-primary px-4 py-2">
                <Icon name="Plus" size={16} className="inline mr-1" /> Build a Plan
              </button>
            )}
          </div>
        </div>

        {/* Plan Builder */}
        {showBuilder && (
          <div className="card p-6 mb-8 space-y-5 border-2 border-primary/20">
            <div className="flex items-center justify-between">
              <h2 className="font-heading font-semibold text-lg text-text-primary">Plan Builder</h2>
              <button onClick={() => setShowBuilder(false)} className="text-text-secondary hover:text-text-primary">
                <Icon name="X" size={20} />
              </button>
            </div>

            {/* Title + Hours */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium text-text-secondary block mb-1">Plan name</label>
                <input
                  type="text"
                  value={planTitle}
                  onChange={(e) => setPlanTitle(e.target.value)}
                  className="w-full px-3 py-2 border border-border rounded-lg bg-background focus:outline-none focus:ring-2 focus:ring-primary text-sm"
                  placeholder="e.g. Midterm Prep"
                />
              </div>
              <div>
                <label className="text-sm font-medium text-text-secondary block mb-1">
                  Hours per week: <span className="text-primary font-bold">{weeklyHours.toFixed(1)}</span>
                </label>
                <input
                  type="range"
                  min={0.5}
                  max={3.6}
                  step={0.1}
                  value={weeklyHours}
                  onChange={(e) => setWeeklyHours(parseFloat(e.target.value))}
                  className="w-full accent-primary"
                />
                <div className="flex justify-between text-xs text-text-secondary mt-1">
                  <span>0.5h</span><span>3.6h max</span>
                </div>
              </div>
            </div>

            {/* Custom topic ideas */}
            <div>
              <label className="text-sm font-medium text-text-secondary block mb-1">
                Custom topic ideas <span className="text-text-secondary font-normal">(optional, comma-separated)</span>
              </label>
              <input
                type="text"
                value={customTopics}
                onChange={(e) => setCustomTopics(e.target.value)}
                placeholder="e.g. machine learning basics, Spanish verbs, organic chemistry"
                className="w-full px-3 py-2 border border-border rounded-lg bg-background focus:outline-none focus:ring-2 focus:ring-primary text-sm"
              />
            </div>

            {/* Catalog search + filter */}
            <div>
              <label className="text-sm font-medium text-text-secondary block mb-2">
                Or pick from catalog ({selectedIds.length} selected)
              </label>
              <div className="flex gap-2 mb-3">
                <div className="relative flex-1">
                  <Icon name="Search" size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-text-secondary" />
                  <input
                    type="text"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="Search topics, concepts..."
                    className="w-full pl-9 pr-3 py-2 border border-border rounded-lg bg-background focus:outline-none focus:ring-2 focus:ring-primary text-sm"
                  />
                </div>
                <select
                  value={subjectFilter}
                  onChange={(e) => setSubjectFilter(e.target.value)}
                  className="px-3 py-2 border border-border rounded-lg bg-background text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                >
                  {SUBJECTS.map((s) => (
                    <option key={s} value={s}>{s === 'all' ? 'All subjects' : s.charAt(0).toUpperCase() + s.slice(1)}</option>
                  ))}
                </select>
              </div>

              <div className="max-h-64 overflow-y-auto space-y-1.5 border border-border rounded-lg p-2 bg-surface-50/50">
                {filteredCatalog.length === 0 && (
                  <p className="text-sm text-text-secondary text-center py-4">No matching courses</p>
                )}
                {filteredCatalog.map((item) => {
                  const isSelected = selectedIds.includes(item.id);
                  const progress = learningNodes.find((n) => n.id === item.id)?.progress || 0;
                  return (
                    <button
                      key={item.id}
                      type="button"
                      onClick={() => toggleSelect(item.id)}
                      className={`w-full text-left px-3 py-2.5 rounded-lg border transition-all flex items-center gap-3 ${
                        isSelected
                          ? 'border-primary bg-primary/10 ring-1 ring-primary/30'
                          : 'border-transparent hover:bg-surface hover:border-border'
                      }`}
                    >
                      <div className={`w-5 h-5 rounded border-2 flex-shrink-0 flex items-center justify-center ${
                        isSelected ? 'border-primary bg-primary text-white' : 'border-border'
                      }`}>
                        {isSelected && <Icon name="Check" size={12} />}
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="font-medium text-sm text-text-primary truncate">{item.title}</p>
                        <p className="text-xs text-text-secondary truncate">
                          {item.subject} · {item.difficulty} · {item.estimatedTime}
                          {progress > 0 && ` · ${progress}% done`}
                        </p>
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Selected summary */}
            {(selectedIds.length > 0 || customTopics.trim()) && (
              <div className="flex flex-wrap gap-1.5">
                {selectedItems.map((item) => (
                  <span key={item.id} className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full bg-primary/10 text-primary text-xs font-medium">
                    {item.title}
                    <button type="button" onClick={() => toggleSelect(item.id)} className="hover:text-primary-700">
                      <Icon name="X" size={12} />
                    </button>
                  </span>
                ))}
                {customTopics.trim() && customTopics.split(',').filter(Boolean).map((t) => (
                  <span key={t.trim()} className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full bg-accent/10 text-accent text-xs font-medium">
                    {t.trim()}
                  </span>
                ))}
              </div>
            )}

            <button
              onClick={createPlan}
              disabled={creating || (selectedIds.length === 0 && !customTopics.trim())}
              className="btn btn-primary w-full py-3 text-sm disabled:opacity-40"
            >
              {creating ? 'Creating plan...' : `Create Plan (${selectedIds.length} topics${customTopics.trim() ? ' + custom' : ''})`}
            </button>
          </div>
        )}

        {/* Active plan */}
        {planData?.plan ? (
          <>
            <div className="card p-6 mb-6">
              <div className="flex items-center justify-between">
                <div>
                  <h2 className="font-heading font-semibold text-lg">{planData.plan.title}</h2>
                  <p className="text-sm text-text-secondary">
                    Target: {(planData.plan.weeklyMinutes / 60).toFixed(1)}h/week · Started {planData.plan.startDate}
                  </p>
                </div>
                <div className="text-right">
                  <p className="text-2xl font-bold text-primary">
                    {planData.calendar.filter((d) => d.completed).length}/{planData.calendar.length}
                  </p>
                  <p className="text-xs text-text-secondary">days done</p>
                </div>
              </div>
            </div>
            <WeeklyCalendar calendar={planData.calendar} onToggleDay={toggleDay} />
          </>
        ) : !showBuilder && (
          <div className="card p-12 text-center">
            <Icon name="Calendar" size={48} className="mx-auto text-primary mb-4" />
            <h2 className="text-xl font-heading font-semibold mb-2">No active plan</h2>
            <p className="text-text-secondary mb-4">
              Search topics, pick from the catalog, or add your own ideas to build a weekly plan.
            </p>
            <button onClick={openBuilder} className="btn btn-primary px-6 py-2">
              Build a Plan
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default StudyPlannerPage;
