import React from 'react';
import { Link } from 'react-router-dom';
import Icon from 'components/AppIcon';

const WeeklyCalendar = ({ calendar = [], onToggleDay }) => {
  return (
    <div className="grid gap-3">
      {calendar.map((entry) => (
        <div
          key={entry.day}
          className={`card p-4 flex flex-col sm:flex-row sm:items-center gap-4 ${
            entry.completed ? 'opacity-75 bg-success-50/30' : ''
          }`}
        >
          <div className="w-16 font-heading font-bold text-primary">{entry.day}</div>
          <div className="flex-1">
            <p className="font-medium text-text-primary">{entry.nodeTitle || 'Review day'}</p>
            <p className="text-sm text-text-secondary">
              {entry.minutes} min planned
              {entry.subject && entry.subject !== 'custom' && ` · ${entry.subject}`}
              {entry.customTopic && ' · custom topic'}
            </p>
          </div>
          <div className="flex items-center gap-2">
            {entry.nodeId && (
              <Link
                to={`/course-catalog`}
                className="btn btn-outline px-3 py-1.5 text-sm"
              >
                Start
              </Link>
            )}
            {entry.customTopic && !entry.nodeId && (
              <Link
                to="/learn-canvas"
                className="btn btn-outline px-3 py-1.5 text-sm"
              >
                Learn
              </Link>
            )}
            <button
              onClick={() => onToggleDay(entry.day)}
              className={`p-2 rounded-lg border ${
                entry.completed ? 'bg-success text-white border-success' : 'border-border'
              }`}
              aria-label={entry.completed ? 'Mark incomplete' : 'Mark complete'}
            >
              <Icon name={entry.completed ? 'Check' : 'Circle'} size={18} />
            </button>
          </div>
        </div>
      ))}
    </div>
  );
};

export default WeeklyCalendar;
